// Real Jet runtime only; link -Wl,--wrap=jet_rt_free.
// Goldens generated by exact rustc 1.97.1 ({:?} for str), NOT JSON escaping.
#include <assert.h>
#include <stdint.h>
#include <stddef.h>
#include <stdio.h>
#include <string.h>
#include "TextDebugGoldens.h"
typedef struct { unsigned char *data; int64_t length,capacity; } Text;
extern void jet_rt_alloc_init(void);
extern void __real_jet_rt_free(void *,int64_t,int64_t);
extern Text *jet_rt_string_from_static(const void *,int64_t);
extern Text *jet_rt_string_builder_new(void);
extern void jet_rt_string_builder_push_static(Text *,const void *,int64_t);
extern Text *jet_rt_string_builder_finish(Text *);
extern void jet_rt_string_drop(Text *);
extern void rt_text_push_rust_debug_str(Text *,Text *);
extern Text *jet_rt_require_debug_string(Text *);
static struct { void *pointer; int64_t size,align; unsigned frees; } watched[8];
static size_t count;
static unsigned intercepted;
void __wrap_jet_rt_free(void *p,int64_t size,int64_t align) {
    ++intercepted;
    for(size_t i=0;i<count;++i) if(watched[i].pointer==p) {
        assert(size==watched[i].size && align==watched[i].align);assert(++watched[i].frees==1);
    }
    __real_jet_rt_free(p,size,align);
}
static void watch(void *p,int64_t size,int64_t align) {
    assert(count<8);for(size_t i=0;i<count;++i) assert(watched[i].pointer!=p);
    watched[count].pointer=p;watched[count].size=size;watched[count].align=align;watched[count++].frees=0;
}
static void watch_text(Text *t) { watch(t,24,8);if(t->capacity) watch(t->data,t->capacity,1); }
int main(void) {
    jet_rt_alloc_init();
    for(size_t i=0;i<sizeof(debug_goldens)/sizeof(debug_goldens[0]);++i) {
        Text *input=jet_rt_string_from_static(debug_goldens[i].input,debug_goldens[i].input_length);
        Text *builder=jet_rt_string_builder_new();
        jet_rt_string_builder_push_static(builder,"prefix:",7);
        rt_text_push_rust_debug_str(builder,input);
        jet_rt_string_builder_push_static(builder,"|",1);
        rt_text_push_rust_debug_str(builder,input);
        Text *output=jet_rt_string_builder_finish(builder);
        assert(output==builder && output!=input);
        int64_t n=debug_goldens[i].expected_length;
        assert(output->length==8+2*n);
        assert(memcmp(output->data,"prefix:",7)==0);
        assert(memcmp(output->data+7,debug_goldens[i].expected,(size_t)n)==0);
        assert(output->data[7+n]=='|');
        assert(memcmp(output->data+8+n,debug_goldens[i].expected,(size_t)n)==0);
        assert(input->length==debug_goldens[i].input_length);
        assert(memcmp(input->data,debug_goldens[i].input,(size_t)input->length)==0);
        Text *jet_debug=jet_rt_require_debug_string(input);
        // D-STR-ESCAPE1 uses \u{0}; Rust str Debug uses \0. Only vector 2
        // contains NUL; every other byte/escape class must match exactly.
        const char *jet_expected=i==2 ? "\"\\u{0}\\t\\r\\n\\u{1}\\u{7}\\u{8}\\u{b}\\u{c}\\u{1b}\\u{1f}\\u{7f}\"" : debug_goldens[i].expected;
        int64_t jet_length=i==2 ? (int64_t)strlen(jet_expected) : n;
        assert(jet_debug->length==jet_length);
        assert(memcmp(jet_debug->data,jet_expected,(size_t)jet_length)==0);
        watch_text(input);watch_text(output);watch_text(jet_debug);unsigned before=intercepted;
        jet_rt_string_drop(input);jet_rt_string_drop(output);jet_rt_string_drop(jet_debug);
        assert(intercepted>before);for(size_t j=0;j<count;++j) assert(watched[j].frees==1);count=0;
    }
    puts("text-debug witness OK (36 pinned Rust vectors)");return 0;
}
